func (this *Blockchaincom) ParseTicker(ticker any, optionalArgs ...any) any {
	//
	//     {
	//     "symbol": "BTC-USD",
	//     "price_24h": 47791.86,
	//     "volume_24h": 362.88635738,
	//     "last_trade_price": 47587.75
	//     }
	//
	market := GetArg(optionalArgs, 0, nil)
	_ = market
	var marketId any = this.SafeString(ticker, "symbol")
	var symbol any = this.SafeSymbol(marketId, market, "-")
	var last any = this.SafeString(ticker, "last_trade_price")
	var baseVolume any = this.SafeString(ticker, "volume_24h")
	var open any = this.SafeString(ticker, "price_24h")
	return this.SafeTicker(map[string]any{
		"symbol":        symbol,
		"timestamp":     nil,
		"datetime":      nil,
		"high":          nil,
		"low":           nil,
		"bid":           nil,
		"bidVolume":     nil,
		"ask":           nil,
		"askVolume":     nil,
		"vwap":          nil,
		"open":          open,
		"close":         nil,
		"last":          last,
		"previousClose": nil,
		"change":        nil,
		"percentage":    nil,
		"average":       nil,
		"baseVolume":    baseVolume,
		"quoteVolume":   nil,
		"info":          ticker,
	}, market)
}

